declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/document_manager.php';require_permission('tickets.view');$pdo=db();$user=current_user();$isAdmin=((string)$user['role']==='admin')||has_permission('settings.manage');$id=(int)($_GET['id']??0);$fetch=function()use($pdo,$id){$s=$pdo->prepare("SELECT t.*,u.name user_name,u.email user_email,a.name assigned_name FROM support_tickets t JOIN users u ON u.id=t.user_id LEFT JOIN users a ON a.id=t.assigned_to WHERE t.id=?");$s->execute([$id]);return $s->fetch();};$ticket=$fetch();if(!$ticket||(!$isAdmin&&(int)$ticket['user_id']!==(int)$user['id'])){http_response_code(404);exit('Ticket no encontrado.');}$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=(string)($_POST['action']??'reply');if($action==='route'&&$isAdmin){$stage=(string)($_POST['stage']??$ticket['stage']);$allowed=['new','triage','in_progress','waiting_user','waiting_internal','resolved','closed'];if(!in_array($stage,$allowed,true))$stage='triage';$assigned=(int)($_POST['assigned_to']??0)?:null;$department=trim((string)($_POST['department']??'Soporte'));$priority=(string)($_POST['priority']??'normal');$sla=trim((string)($_POST['sla_due_at']??''));$follow=trim((string)($_POST['next_follow_up_at']??''));$resolution=trim((string)($_POST['resolution']??''));$status=in_array($stage,['resolved','closed'],true)?$stage:'open';$closed=$stage==='closed'?date('Y-m-d H:i:s'):null;$pdo->prepare("UPDATE support_tickets SET assigned_to=?,department=?,priority=?,stage=?,status=?,sla_due_at=?,next_follow_up_at=?,resolution=?,closed_at=? WHERE id=?")->execute([$assigned,$department?:'Soporte',$priority,$stage,$status,$sla?date('Y-m-d H:i:s',strtotime($sla)):null,$follow?date('Y-m-d H:i:s',strtotime($follow)):null,$resolution,$closed,$id]);$pdo->prepare("INSERT INTO support_ticket_events(ticket_id,user_id,event_type,title,details) VALUES(?,?,?,?,?)")->execute([$id,(int)$user['id'],'route','Ruta actualizada','Etapa: '.str_replace('_',' ',$stage).' · Prioridad: '.$priority]);flash('success','Ruta y seguimiento actualizados.');redirect('support_ticket_view.php?id='.$id);}if($action==='reply'){ $message=trim((string)($_POST['message']??''));$internal=$isAdmin&&!empty($_POST['is_internal']);if($message==='')$errors[]='Escribe una respuesta.';else{$pdo->prepare("INSERT INTO support_ticket_messages(ticket_id,user_id,message,is_internal) VALUES(?,?,?,?)")->execute([$id,(int)$user['id'],$message,$internal?1:0]);$pdo->prepare('UPDATE support_tickets SET last_reply_by=?,updated_at=NOW() WHERE id=?')->execute([(int)$user['id'],$id]);$pdo->prepare("INSERT INTO support_ticket_events(ticket_id,user_id,event_type,title,details) VALUES(?,?,?,?,?)")->execute([$id,(int)$user['id'],$internal?'internal_note':'reply',$internal?'Nota interna':'Respuesta agregada',crm_strimwidth($message,100)]);if(!$internal){$to=$isAdmin?$ticket['user_email']:(string)setting('support_email','info@socrates.la');$mail=send_system_email($to,'Ticket '.$ticket['ticket_number'].' · '.$ticket['subject'],'<p>'.nl2br(e($message)).'</p><p><a href="'.e(app_url('support_ticket_view.php?id='.$id)).'">Abrir ticket</a></p>');flash($mail['success']?'success':'info',$mail['success']?'Respuesta guardada y notificada por email.':'Respuesta guardada, pero el email falló: '.$mail['error']);}else flash('success','Nota interna guardada.');redirect('support_ticket_view.php?id='.$id);}}}
$ticket=$fetch();$m=$pdo->prepare("SELECT m.*,u.name user_name,u.role FROM support_ticket_messages m LEFT JOIN users u ON u.id=m.user_id WHERE m.ticket_id=? ".(!$isAdmin?'AND m.is_internal=0 ':'')."ORDER BY m.created_at");$m->execute([$id]);$messages=$m->fetchAll();$ev=$pdo->prepare("SELECT e.*,u.name user_name FROM support_ticket_events e LEFT JOIN users u ON u.id=e.user_id WHERE e.ticket_id=? ORDER BY e.created_at DESC LIMIT 40");$ev->execute([$id]);$events=$ev->fetchAll();$admins=$isAdmin?$pdo->query("SELECT id,name FROM users WHERE is_active=1 AND role IN ('admin','manager') ORDER BY name")->fetchAll():[];$pageTitle='Ticket '.$ticket['ticket_number'];require __DIR__.'/includes/header.php';?>
<?php foreach($errors as$e):?><div class="alert alert-error"><?=e($e)?></div><?php endforeach;?><div class="project-hero compact"><div><span class="eyebrow">HELPDESK · <?=e($ticket['ticket_number'])?></span><h2><?=e($ticket['subject'])?></h2><p><?=e($ticket['user_name'])?> · <?=e($ticket['department'])?> · <?=e(ucfirst($ticket['priority']))?></p></div><div class="actions"><span class="ticket-stage <?=e($ticket['stage'])?>"><?=e(ucfirst(str_replace('_',' ',$ticket['stage'])))?></span><a class="btn btn-light" href="support.php">← VOLVER</a></div></div>
<div class="support-case-grid"><section class="panel"><div class="panel-header"><div><h2>Conversación</h2><span class="table-sub">La primera solicitud y todas las respuestas quedan trazadas.</span></div></div><div class="panel-body"><div class="support-thread"><article class="support-message"><strong><?=e($ticket['user_name'])?></strong><small><?=e(format_date_time($ticket['created_at']))?></small><p><?=nl2br(e($ticket['message']))?></p></article><?php foreach($messages as$msg):?><article class="support-message <?=$msg['is_internal']?'internal':''?>"><strong><?=e($msg['user_name']?:'Sistema')?><?=$msg['is_internal']?' · NOTA INTERNA':''?></strong><small><?=e(format_date_time($msg['created_at']))?></small><p><?=nl2br(e($msg['message']))?></p></article><?php endforeach;?></div><form method="post" class="support-reply"><?=csrf_field()?><textarea name="message" rows="5" placeholder="Escribe una respuesta o actualización…" required></textarea><?php if($isAdmin):?><label class="checkbox-row"><input type="checkbox" name="is_internal" value="1"> Guardar como nota interna (no se envía al usuario)</label><?php endif;?><button class="btn btn-primary" name="action" value="reply">RESPONDER</button></form></div></section>
<aside><section class="panel"><div class="panel-header"><h2><?=$isAdmin?'Ruta y seguimiento':'Estado del caso'?></h2></div><div class="panel-body"><?php if($isAdmin):?><form method="post" class="form-grid"><?=csrf_field()?><label>Etapa<select name="stage"><?php foreach(['new'=>'Nuevo','triage'=>'Clasificación','in_progress'=>'En trabajo','waiting_user'=>'Esperando usuario','waiting_internal'=>'Esperando interno','resolved'=>'Resuelto','closed'=>'Cerrado'] as$k=>$v):?><option value="<?=$k?>" <?=$ticket['stage']===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></label><label>Responsable<select name="assigned_to"><option value="0">Sin asignar</option><?php foreach($admins as$a):?><option value="<?=$a['id']?>" <?=(int)$ticket['assigned_to']===(int)$a['id']?'selected':''?>><?=e($a['name'])?></option><?php endforeach;?></select></label><label>Departamento<input name="department" value="<?=e($ticket['department'])?>"></label><label>Prioridad<select name="priority"><?php foreach(['low'=>'Baja','normal'=>'Normal','high'=>'Alta','urgent'=>'Urgente'] as$k=>$v):?><option value="<?=$k?>" <?=$ticket['priority']===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></label><label>SLA objetivo<input type="datetime-local" name="sla_due_at" value="<?=e($ticket['sla_due_at']?date('Y-m-d\TH:i',strtotime($ticket['sla_due_at'])):'')?>"></label><label>Próximo seguimiento<input type="datetime-local" name="next_follow_up_at" value="<?=e($ticket['next_follow_up_at']?date('Y-m-d\TH:i',strtotime($ticket['next_follow_up_at'])):'')?>"></label><label class="full">Resolución / siguiente paso<textarea name="resolution"><?=e($ticket['resolution']??'')?></textarea></label><div class="full"><button class="btn btn-secondary btn-block" name="action" value="route">ACTUALIZAR RUTA</button></div></form><?php else:?><div class="details-grid" style="grid-template-columns:1fr"><div class="detail"><small>Etapa</small><strong><?=e(ucfirst(str_replace('_',' ',$ticket['stage'])))?></strong></div><div class="detail"><small>Responsable</small><strong><?=e($ticket['assigned_name']?:'Equipo de soporte')?></strong></div><div class="detail"><small>Próximo seguimiento</small><strong><?=e(format_date_time($ticket['next_follow_up_at']))?></strong></div></div><?php endif;?></div></section><section class="panel"><div class="panel-header"><h2>Trazabilidad</h2></div><div class="panel-body"><div class="ticket-timeline"><?php foreach($events as$e):?><div class="ticket-event"><strong><?=e($e['title'])?></strong><small><?=e($e['user_name']?:'Sistema')?> · <?=e(format_date_time($e['created_at']))?></small><?php if($e['details']):?><p><?=e($e['details'])?></p><?php endif;?></div><?php endforeach;?></div></div></section></aside></div><?php if(has_permission('documents.view'))echo dms_related_panel('ticket',$id);?><?php require __DIR__.'/includes/footer.php';?>
